<template><section><div class="page-head"><div><h2>Manajemen Nilai</h2><p>Kelas {{ classroom }} · {{ subjects.length }} mata pelajaran · KKM 75</p></div><button class="btn btn-primary btn-sm" type="button" @click="exportLedger"><AdminIcon name="dl" size="16" /> Ekspor Leger</button></div><div class="toolbar"><button v-for="item in ['SMP','SMK']" :key="item" class="chip" :class="{ on: level === item }" type="button" @click="level = item; classroom = item === 'SMP' ? 'IX-A' : 'X RPL 1'">{{ item }}</button><select v-model="classroom" class="sel"><option v-if="level === 'SMP'">IX-A</option><option v-if="level === 'SMP'">VIII-B</option><option v-if="level === 'SMK'">X RPL 1</option><option v-if="level === 'SMK'">XI TKJ 1</option></select><select v-model="subject" class="sel"><option value="Semua">Semua Mapel</option><option v-for="item in subjects" :key="item">{{ item }}</option></select><label class="inp"><span class="ic"><AdminIcon name="search" size="17" /></span><input v-model.trim="query" placeholder="Cari siswa…" /></label></div><div class="grid g4" style="margin-bottom:18px"><article v-for="item in metrics" :key="item.label" class="kpi" :class="item.color"><span class="shine" /><div class="k-lbl" style="font-size:14px;font-weight:700;color:#fff">{{ item.label }}</div><div class="k-val">{{ item.value }}</div><div class="k-lbl">{{ item.note }}</div></article></div><div class="card"><div class="tbl-wrap"><table class="tbl rt"><thead><tr><th>Siswa</th><th>NIS</th><th>{{ subject === 'Semua' ? 'Rata-rata' : subject }}</th><th>Predikat</th><th>Status</th></tr></thead><tbody><tr v-for="item in rows" :key="item.nis"><td><div class="row-user"><span class="ava">{{ initials(item.name) }}</span><b class="t-name">{{ item.name }}</b></div></td><td>{{ item.nis }}</td><td><b :style="{ color: score(item) >= 75 ? 'var(--green)' : 'var(--rose)' }">{{ score(item).toFixed(1) }}</b></td><td><span class="pill" :class="gradeClass(score(item))">{{ grade(score(item)) }}</span></td><td><span class="pill" :class="score(item) >= 75 ? 'p-green' : 'p-rose'">{{ score(item) >= 75 ? 'Tuntas' : 'Remidi' }}</span></td></tr><tr v-if="!rows.length"><td colspan="5"><div class="empty">Tidak ada siswa yang cocok.</div></td></tr></tbody></table></div></div></section></template>
<script setup lang="ts">definePageMeta({layout:'admin'}); type Student={name:string;nis:string;nilai:Record<string,number>}; const level=ref('SMP');const classroom=ref('IX-A');const subject=ref('Semua');const query=ref('');const subjects=['Matematika','IPA','Bahasa Indonesia','Informatika'];const students:Student[]=[{name:'Ahmad Fauzan',nis:'2026001',nilai:{Matematika:84,IPA:82,'Bahasa Indonesia':86,Informatika:88}},{name:'Siti Aisyah',nis:'2026002',nilai:{Matematika:91,IPA:89,'Bahasa Indonesia':92,Informatika:90}},{name:'Muhammad Rizky',nis:'2026019',nilai:{Matematika:73,IPA:76,'Bahasa Indonesia':75,Informatika:78}},{name:'Nabila Zahra',nis:'2026103',nilai:{Matematika:79,IPA:81,'Bahasa Indonesia':84,Informatika:86}}];const rows=computed(()=>students.filter(item=>`${item.name} ${item.nis}`.toLowerCase().includes(query.value.toLowerCase())));const score=(item:Student)=>subject.value==='Semua'?Object.values(item.nilai).reduce((a,b)=>a+b,0)/subjects.length:item.nilai[subject.value];const grade=(value:number)=>value>=90?'A':value>=80?'B':value>=75?'C':'D';const gradeClass=(value:number)=>({A:'p-green',B:'p-blue',C:'p-amber',D:'p-rose'})[grade(value)];const metrics=computed(()=>[{label:'Rata-rata Kelas',value:(students.reduce((sum,item)=>sum+score(item),0)/students.length).toFixed(1),color:'k-blue',note:'Di atas KKM'},{label:'Tuntas (≥75)',value:students.filter(item=>score(item)>=75).length,color:'k-green',note:'siswa'},{label:'Nilai Tertinggi',value:Math.max(...students.map(score)).toFixed(0),color:'k-amber',note:'nilai terbaik'},{label:'Mapel Terkuat',value:'Informatika',color:'k-violet',note:'rata-rata tertinggi'}]);const initials=(value:string)=>value.split(' ').slice(0,2).map(item=>item[0]).join('');const exportLedger=()=>window.alert('Leger nilai diekspor ke Excel.')</script>
